<?php
require_once '../config/db.php'; require_once 'auth.php';
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];try{$s=$pdo->prepare('DELETE FROM categories WHERE category_id=?');$s->execute([$id]);header('Location: categories.php?deleted=1');exit;}catch(PDOException $e){$deleteError='This category cannot be deleted because it may be used by an attraction.';}}
$pageTitle='Manage Categories';$rows=$pdo->query('SELECT c.category_id,c.category_name,COUNT(a.attraction_id) attraction_count FROM categories c LEFT JOIN attractions a ON a.category_id=c.category_id GROUP BY c.category_id,c.category_name ORDER BY c.category_name')->fetchAll(PDO::FETCH_ASSOC);include 'header.php';
?><div class="page-actions"><a class="btn" href="category_form.php">+ Add Category</a></div><?php if(isset($_GET['deleted'])):?><div class="alert success">Category deleted successfully.</div><?php endif; ?><?php if(isset($deleteError)): ?><div class="alert error"><?=htmlspecialchars($deleteError)?></div><?php endif; ?><section class="card"><div class="table-wrap"><table><thead><tr><th>ID</th><th>Category Name</th><th>Attractions</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=$r['category_id']?></td><td><strong><?=htmlspecialchars($r['category_name'])?></strong></td><td><?=$r['attraction_count']?></td><td><a class="btn small" href="category_form.php?id=<?=$r['category_id']?>">Edit</a><a class="btn small danger-btn" href="categories.php?delete=<?=$r['category_id']?>" onclick="return confirm('Delete this category?')">Delete</a></td></tr><?php endforeach; ?></tbody></table></div></section><?php include 'footer.php'; ?>
